import React, { useState, useEffect, useCallback } from 'react';
import { useNavigate } from 'react-router-dom';

const API = process.env.REACT_APP_API_URL || 'http://localhost:5000';

interface Announcement {
  id: string;
  title: string;
  content: string;
  priority: 'normal' | 'important' | 'urgent';
  created_at: string;
}

interface StudentProfile {
  studentId: string;
  firstName: string;
  lastName: string;
  otherNames: string | null;
  email: string;
  phone: string;
  dateOfBirth: string;
  gender: string;
  nationality: string;
  hometown: string;
  postalAddress: string;
  programme: string;
  programmeId: string;
  enrollmentOption: string;
  applicationType: string;
  status: string;
  applicationId: string;
  admissionLetterUrl: string | null;
  submittedAt: string;
  approvedAt: string;
  createdAt: string;
}

interface FeeBreakdown {
  tuitionFee: number;
  facilityFee: number;
  libraryFee: number;
  ictFee: number;
  examinationFee: number;
  registrationFee: number;
  otherFees: number;
  otherFeesLabel: string | null;
}

interface FeeInfo {
  programmeLabel: string;
  academicYear: string;
  enrollmentOption: string;
  durationYears: number;
  breakdown: FeeBreakdown;
  totalFee: number;
  payment: {
    bankName: string;
    bankBranch: string;
    bankAccountNo: string;
    bankAccountName: string;
    initialPaymentPercent: number;
    initialPaymentDeadline: string;
    balancePaymentDeadline: string;
    programmeStartDate: string;
  };
}

type Tab = 'dashboard' | 'fees' | 'profile' | 'password';

const StudentDashboard: React.FC = () => {
  const [activeTab, setActiveTab] = useState<Tab>('dashboard');
  const [profile, setProfile] = useState<StudentProfile | null>(null);
  const [fees, setFees] = useState<FeeInfo | null>(null);
  const [announcements, setAnnouncements] = useState<Announcement[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const navigate = useNavigate();

  // Password change state
  const [currentPassword, setCurrentPassword] = useState('');
  const [newPassword, setNewPassword] = useState('');
  const [confirmPassword, setConfirmPassword] = useState('');
  const [pwLoading, setPwLoading] = useState(false);
  const [pwMessage, setPwMessage] = useState('');

  // Profile update state
  const [editPhone, setEditPhone] = useState('');
  const [editAddress, setEditAddress] = useState('');
  const [profileLoading, setProfileLoading] = useState(false);
  const [profileMessage, setProfileMessage] = useState('');

  const getToken = () => localStorage.getItem('studentToken');

  const logout = () => {
    localStorage.removeItem('studentToken');
    localStorage.removeItem('studentInfo');
    navigate('/student/login');
  };

  const authFetch = useCallback(async (url: string, options: RequestInit = {}) => {
    const token = getToken();
    if (!token) { navigate('/student/login'); return null; }
    const res = await fetch(url, {
      ...options,
      headers: { ...options.headers, 'Content-Type': 'application/json', Authorization: `Bearer ${token}` },
    });
    if (res.status === 401 || res.status === 403) { 
      localStorage.removeItem('studentToken');
      localStorage.removeItem('studentInfo');
      navigate('/student/login'); 
      return null; 
    }
    return res.json();
  }, [navigate]);

  useEffect(() => {
    const loadData = async () => {
      setLoading(true);
      try {
        const [profileData, feeData, announcementData] = await Promise.all([
          authFetch(`${API}/api/students/profile`),
          authFetch(`${API}/api/students/fees`),
          authFetch(`${API}/api/students/announcements`),
        ]);
        if (profileData?.success) {
          setProfile(profileData.profile);
          setEditPhone(profileData.profile.phone);
          setEditAddress(profileData.profile.postalAddress);
        }
        if (feeData?.success) setFees(feeData.fees);
        if (announcementData?.success) setAnnouncements(announcementData.announcements || []);
      } catch {
        setError('Failed to load data');
      } finally {
        setLoading(false);
      }
    };
    loadData();
  }, [authFetch]);

  const handleChangePassword = async (e: React.FormEvent) => {
    e.preventDefault();
    if (newPassword !== confirmPassword) {
      setPwMessage('Passwords do not match');
      return;
    }
    setPwLoading(true);
    setPwMessage('');
    try {
      const data = await authFetch(`${API}/api/students/change-password`, {
        method: 'POST',
        body: JSON.stringify({ currentPassword, newPassword }),
      });
      if (data?.success) {
        setPwMessage('Password changed successfully!');
        setCurrentPassword('');
        setNewPassword('');
        setConfirmPassword('');
      } else {
        setPwMessage(data?.message || 'Failed to change password');
      }
    } catch {
      setPwMessage('Network error');
    } finally {
      setPwLoading(false);
    }
  };

  const handleUpdateProfile = async (e: React.FormEvent) => {
    e.preventDefault();
    setProfileLoading(true);
    setProfileMessage('');
    try {
      const data = await authFetch(`${API}/api/students/profile`, {
        method: 'PUT',
        body: JSON.stringify({ phone: editPhone, postalAddress: editAddress }),
      });
      if (data?.success) {
        setProfileMessage('Profile updated!');
        setProfile(prev => prev ? { ...prev, phone: editPhone, postalAddress: editAddress } : null);
      } else {
        setProfileMessage(data?.message || 'Update failed');
      }
    } catch {
      setProfileMessage('Network error');
    } finally {
      setProfileLoading(false);
    }
  };

  if (loading) {
    return (
      <div style={{ display: 'flex', justifyContent: 'center', alignItems: 'center', minHeight: '100vh' }}>
        <p>Loading...</p>
      </div>
    );
  }

  const studentInfo = profile;
  const formatCurrency = (n: number) => `GHS ${n.toLocaleString('en-GH', { minimumFractionDigits: 2 })}`;

  return (
    <div>
      {/* Header */}
      <header className="header">
        <div className="header-content">
          <div className="logo-section">
            <img src="http://wuc.edu.gh/wp-content/uploads/2025/05/WC-logo-on-white-1.jpg" alt="WUC Logo" />
            <div>
              <h1>Withrow University College</h1>
              <span className="logo-sub">Student Portal</span>
            </div>
          </div>
          <nav>
            <ul className="nav-links">
              <li><span style={{ color: 'rgba(255,255,255,0.7)', fontSize: '0.8rem' }}>
                {studentInfo?.firstName} {studentInfo?.lastName}
              </span></li>
              <li><button onClick={logout} className="btn btn-ghost btn-sm" style={{ color: 'white', borderColor: 'rgba(255,255,255,0.3)' }}>Logout</button></li>
            </ul>
          </nav>
        </div>
      </header>

      <div style={{ maxWidth: '1100px', margin: '0 auto', padding: '1.5rem' }}>
        {error && <div className="alert alert-error">{error}</div>}

        {/* Tab navigation */}
        <div style={{
          display: 'flex', gap: '0.25rem', marginBottom: '1.5rem',
          borderBottom: '2px solid var(--border)', paddingBottom: '0',
        }}>
          {([
            { key: 'dashboard', label: '📊 Dashboard' },
            { key: 'fees', label: '💰 Fees' },
            { key: 'profile', label: '👤 Profile' },
            { key: 'password', label: '🔒 Password' },
          ] as { key: Tab; label: string }[]).map(tab => (
            <button
              key={tab.key}
              onClick={() => setActiveTab(tab.key)}
              style={{
                padding: '0.75rem 1.25rem', border: 'none', background: 'none',
                cursor: 'pointer', fontSize: '0.85rem', fontWeight: 600,
                color: activeTab === tab.key ? 'var(--primary)' : 'var(--text-muted)',
                borderBottom: activeTab === tab.key ? '2px solid var(--primary)' : '2px solid transparent',
                marginBottom: '-2px', transition: 'all 0.2s',
              }}
            >
              {tab.label}
            </button>
          ))}
        </div>

        {/* Dashboard Tab */}
        {activeTab === 'dashboard' && studentInfo && (
          <div>
            {/* Welcome Card */}
            <div className="card" style={{ background: 'linear-gradient(135deg, var(--primary) 0%, var(--primary-mid) 100%)', color: 'white', border: 'none' }}>
              <h2 style={{ fontSize: '1.5rem', fontWeight: 700, marginBottom: '0.5rem', color: 'white' }}>
                Welcome, {studentInfo.firstName}! 🎓
              </h2>
              <p style={{ color: 'rgba(255,255,255,0.8)', marginBottom: '1rem' }}>
                Student ID: <strong>{studentInfo.studentId}</strong>
              </p>
              <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(200px, 1fr))', gap: '1rem' }}>
                <div style={{ background: 'rgba(255,255,255,0.1)', borderRadius: '8px', padding: '1rem' }}>
                  <div style={{ fontSize: '0.7rem', textTransform: 'uppercase', letterSpacing: '0.05em', color: 'rgba(255,255,255,0.6)', marginBottom: '0.25rem' }}>Programme</div>
                  <div style={{ fontWeight: 600, fontSize: '0.9rem' }}>{studentInfo.programme || 'Not assigned'}</div>
                </div>
                <div style={{ background: 'rgba(255,255,255,0.1)', borderRadius: '8px', padding: '1rem' }}>
                  <div style={{ fontSize: '0.7rem', textTransform: 'uppercase', letterSpacing: '0.05em', color: 'rgba(255,255,255,0.6)', marginBottom: '0.25rem' }}>Enrollment</div>
                  <div style={{ fontWeight: 600, fontSize: '0.9rem' }}>{studentInfo.enrollmentOption}</div>
                </div>
                <div style={{ background: 'rgba(255,255,255,0.1)', borderRadius: '8px', padding: '1rem' }}>
                  <div style={{ fontSize: '0.7rem', textTransform: 'uppercase', letterSpacing: '0.05em', color: 'rgba(255,255,255,0.6)', marginBottom: '0.25rem' }}>Type</div>
                  <div style={{ fontWeight: 600, fontSize: '0.9rem' }}>{studentInfo.applicationType === 'topup' ? 'Top-Up' : 'Regular'}</div>
                </div>
              </div>
            </div>

            {/* Quick Actions */}
            <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(240px, 1fr))', gap: '1rem', marginTop: '1.25rem' }}>
              <div className="card" style={{ margin: 0, cursor: 'pointer' }} onClick={() => setActiveTab('fees')}>
                <h4 style={{ color: 'var(--primary)', marginBottom: '0.5rem' }}>💰 Fee Information</h4>
                <p style={{ fontSize: '0.85rem', color: 'var(--text-secondary)' }}>
                  View your fee breakdown, payment details, and deadlines.
                </p>
              </div>
              <div className="card" style={{ margin: 0, cursor: 'pointer' }} onClick={() => setActiveTab('password')}>
                <h4 style={{ color: 'var(--primary)', marginBottom: '0.5rem' }}>🔒 Change Password</h4>
                <p style={{ fontSize: '0.85rem', color: 'var(--text-secondary)' }}>
                  Update your password for security.
                </p>
              </div>
              <div className="card" style={{ margin: 0, cursor: 'pointer' }} onClick={() => setActiveTab('profile')}>
                <h4 style={{ color: 'var(--primary)', marginBottom: '0.5rem' }}>👤 My Profile</h4>
                <p style={{ fontSize: '0.85rem', color: 'var(--text-secondary)' }}>
                  View and update your personal information.
                </p>
              </div>
            </div>

            {/* Key Dates */}
            {fees && (
              <div className="card" style={{ marginTop: '1.25rem' }}>
                <h3 className="section-title">Important Dates</h3>
                <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(200px, 1fr))', gap: '1rem' }}>
                  <div style={{ padding: '0.75rem', background: 'var(--success-bg)', borderRadius: '8px', border: '1px solid var(--success-border)' }}>
                    <div style={{ fontSize: '0.7rem', fontWeight: 700, color: 'var(--success)', textTransform: 'uppercase', marginBottom: '0.25rem' }}>Programme Start</div>
                    <div style={{ fontWeight: 600, color: 'var(--primary)' }}>{fees.payment.programmeStartDate}</div>
                  </div>
                  <div style={{ padding: '0.75rem', background: 'var(--warning-bg)', borderRadius: '8px', border: '1px solid var(--accent)' }}>
                    <div style={{ fontSize: '0.7rem', fontWeight: 700, color: 'var(--accent-dark)', textTransform: 'uppercase', marginBottom: '0.25rem' }}>Initial Payment Due</div>
                    <div style={{ fontWeight: 600, color: 'var(--primary)' }}>{fees.payment.initialPaymentDeadline}</div>
                  </div>
                  <div style={{ padding: '0.75rem', background: 'var(--surface-2)', borderRadius: '8px', border: '1px solid var(--border)' }}>
                    <div style={{ fontSize: '0.7rem', fontWeight: 700, color: 'var(--text-muted)', textTransform: 'uppercase', marginBottom: '0.25rem' }}>Balance Payment Due</div>
                    <div style={{ fontWeight: 600, color: 'var(--primary)' }}>{fees.payment.balancePaymentDeadline}</div>
                  </div>
                </div>
              </div>
            )}
          </div>
        )}

        {/* Fees Tab */}
        {activeTab === 'fees' && (
          <div>
            {!fees ? (
              <div className="card">
                <div className="alert alert-warning">
                  Fee structure is not yet available for your programme. Please check back later or contact the admissions office.
                </div>
              </div>
            ) : (
              <>
                <div className="card">
                  <h3 className="section-title">Fee Structure — {fees.academicYear}</h3>
                  <p className="section-subtitle">{fees.programmeLabel} • {fees.enrollmentOption} • {fees.durationYears}-year programme</p>

                  <table style={{ width: '100%', borderCollapse: 'collapse', marginTop: '1rem' }}>
                    <thead>
                      <tr style={{ borderBottom: '2px solid var(--border)' }}>
                        <th style={{ textAlign: 'left', padding: '0.75rem 0.5rem', fontSize: '0.8rem', fontWeight: 700, color: 'var(--text-muted)', textTransform: 'uppercase' }}>Fee Item</th>
                        <th style={{ textAlign: 'right', padding: '0.75rem 0.5rem', fontSize: '0.8rem', fontWeight: 700, color: 'var(--text-muted)', textTransform: 'uppercase' }}>Amount</th>
                      </tr>
                    </thead>
                    <tbody>
                      {[
                        { label: 'Tuition Fee', amount: fees.breakdown.tuitionFee },
                        { label: 'Facility Fee', amount: fees.breakdown.facilityFee },
                        { label: 'Library Fee', amount: fees.breakdown.libraryFee },
                        { label: 'ICT Fee', amount: fees.breakdown.ictFee },
                        { label: 'Examination Fee', amount: fees.breakdown.examinationFee },
                        { label: 'Registration Fee', amount: fees.breakdown.registrationFee },
                        ...(fees.breakdown.otherFees > 0 ? [{ label: fees.breakdown.otherFeesLabel || 'Other Fees', amount: fees.breakdown.otherFees }] : []),
                      ].map(item => (
                        <tr key={item.label} style={{ borderBottom: '1px solid var(--border)' }}>
                          <td style={{ padding: '0.75rem 0.5rem', fontSize: '0.9rem' }}>{item.label}</td>
                          <td style={{ padding: '0.75rem 0.5rem', fontSize: '0.9rem', textAlign: 'right', fontWeight: 500 }}>{formatCurrency(item.amount)}</td>
                        </tr>
                      ))}
                      <tr style={{ background: 'var(--primary)', color: 'white' }}>
                        <td style={{ padding: '0.875rem 0.5rem', fontSize: '1rem', fontWeight: 700 }}>Total</td>
                        <td style={{ padding: '0.875rem 0.5rem', fontSize: '1rem', fontWeight: 700, textAlign: 'right' }}>{formatCurrency(fees.totalFee)}</td>
                      </tr>
                    </tbody>
                  </table>
                </div>

                <div className="card" style={{ marginTop: '1.25rem' }}>
                  <h3 className="section-title">Payment Information</h3>
                  <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(250px, 1fr))', gap: '1.25rem' }}>
                    <div>
                      <h4 style={{ fontSize: '0.85rem', fontWeight: 700, color: 'var(--primary)', marginBottom: '0.75rem' }}>Bank Details</h4>
                      <div style={{ display: 'flex', flexDirection: 'column', gap: '0.5rem' }}>
                        {[
                          { label: 'Bank', value: fees.payment.bankName },
                          { label: 'Branch', value: fees.payment.bankBranch },
                          { label: 'Account No.', value: fees.payment.bankAccountNo },
                          { label: 'Account Name', value: fees.payment.bankAccountName },
                        ].map(item => (
                          <div key={item.label} style={{ display: 'flex', justifyContent: 'space-between', fontSize: '0.85rem' }}>
                            <span style={{ color: 'var(--text-muted)' }}>{item.label}:</span>
                            <strong>{item.value}</strong>
                          </div>
                        ))}
                      </div>
                    </div>
                    <div>
                      <h4 style={{ fontSize: '0.85rem', fontWeight: 700, color: 'var(--primary)', marginBottom: '0.75rem' }}>Payment Schedule</h4>
                      <div style={{ display: 'flex', flexDirection: 'column', gap: '0.75rem' }}>
                        <div style={{ padding: '0.75rem', background: 'var(--success-bg)', borderRadius: '6px', border: '1px solid var(--success-border)' }}>
                          <div style={{ fontSize: '0.75rem', fontWeight: 700, color: 'var(--success)', marginBottom: '0.25rem' }}>
                            Initial Payment ({fees.payment.initialPaymentPercent}%)
                          </div>
                          <div style={{ fontWeight: 700, fontSize: '1.1rem', color: 'var(--primary)' }}>
                            {formatCurrency(fees.totalFee * fees.payment.initialPaymentPercent / 100)}
                          </div>
                          <div style={{ fontSize: '0.75rem', color: 'var(--text-muted)', marginTop: '0.25rem' }}>
                            Due by {fees.payment.initialPaymentDeadline}
                          </div>
                        </div>
                        <div style={{ padding: '0.75rem', background: 'var(--surface-2)', borderRadius: '6px', border: '1px solid var(--border)' }}>
                          <div style={{ fontSize: '0.75rem', fontWeight: 700, color: 'var(--text-muted)', marginBottom: '0.25rem' }}>
                            Balance ({100 - fees.payment.initialPaymentPercent}%)
                          </div>
                          <div style={{ fontWeight: 700, fontSize: '1.1rem', color: 'var(--primary)' }}>
                            {formatCurrency(fees.totalFee * (100 - fees.payment.initialPaymentPercent) / 100)}
                          </div>
                          <div style={{ fontSize: '0.75rem', color: 'var(--text-muted)', marginTop: '0.25rem' }}>
                            Due by {fees.payment.balancePaymentDeadline}
                          </div>
                        </div>
                      </div>
                    </div>
                  </div>
                </div>
              </>
            )}
          </div>
        )}

        {/* Profile Tab */}
        {activeTab === 'profile' && studentInfo && (
          <div>
            <div className="card">
              <h3 className="section-title">Personal Information</h3>
              <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(220px, 1fr))', gap: '1rem' }}>
                {[
                  { label: 'Student ID', value: studentInfo.studentId },
                  { label: 'Full Name', value: `${studentInfo.firstName} ${studentInfo.otherNames || ''} ${studentInfo.lastName}`.trim() },
                  { label: 'Email', value: studentInfo.email },
                  { label: 'Phone', value: studentInfo.phone },
                  { label: 'Date of Birth', value: studentInfo.dateOfBirth ? new Date(studentInfo.dateOfBirth).toLocaleDateString() : '—' },
                  { label: 'Gender', value: studentInfo.gender },
                  { label: 'Nationality', value: studentInfo.nationality },
                  { label: 'Hometown', value: studentInfo.hometown },
                  { label: 'Postal Address', value: studentInfo.postalAddress },
                  { label: 'Application ID', value: studentInfo.applicationId || '—' },
                  { label: 'Admitted', value: studentInfo.approvedAt ? new Date(studentInfo.approvedAt).toLocaleDateString() : '—' },
                ].map(item => (
                  <div key={item.label} className="detail-row">
                    <span className="detail-label">{item.label}</span>
                    <span className="detail-value">{item.value}</span>
                  </div>
                ))}
              </div>
            </div>

            <div className="card" style={{ marginTop: '1.25rem' }}>
              <h3 className="section-title">Update Contact Information</h3>
              <p className="section-subtitle">You can update your phone number and postal address.</p>
              {profileMessage && (
                <div className={`alert ${profileMessage.includes('updated') ? 'alert-success' : 'alert-error'}`} style={{ marginBottom: '1rem' }}>
                  {profileMessage}
                </div>
              )}
              <form onSubmit={handleUpdateProfile}>
                <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(250px, 1fr))', gap: '1rem' }}>
                  <div className="form-group">
                    <label>Phone Number</label>
                    <input type="text" value={editPhone} onChange={e => setEditPhone(e.target.value)} />
                  </div>
                  <div className="form-group">
                    <label>Postal Address</label>
                    <input type="text" value={editAddress} onChange={e => setEditAddress(e.target.value)} />
                  </div>
                </div>
                <button type="submit" className="btn btn-primary" disabled={profileLoading}>
                  {profileLoading ? 'Saving...' : 'Update Profile'}
                </button>
              </form>
            </div>
          </div>
        )}

        {/* Password Tab */}
        {activeTab === 'password' && (
          <div className="card" style={{ maxWidth: '480px' }}>
            <h3 className="section-title">Change Password</h3>
            <p className="section-subtitle">Choose a strong password with at least 8 characters, one uppercase letter, and one number.</p>
            {pwMessage && (
              <div className={`alert ${pwMessage.includes('successfully') ? 'alert-success' : 'alert-error'}`} style={{ marginBottom: '1rem' }}>
                {pwMessage}
              </div>
            )}
            <form onSubmit={handleChangePassword}>
              <div className="form-group">
                <label>Current Password *</label>
                <input type="password" value={currentPassword} onChange={e => setCurrentPassword(e.target.value)} required />
              </div>
              <div className="form-group">
                <label>New Password *</label>
                <input type="password" value={newPassword} onChange={e => setNewPassword(e.target.value)} required minLength={8} />
              </div>
              <div className="form-group">
                <label>Confirm New Password *</label>
                <input type="password" value={confirmPassword} onChange={e => setConfirmPassword(e.target.value)} required />
              </div>
              <button type="submit" className="btn btn-primary" disabled={pwLoading}>
                {pwLoading ? 'Changing...' : 'Change Password'}
              </button>
            </form>
          </div>
        )}
      </div>
    </div>
  );
};

export default StudentDashboard;
